import React, {useEffect, useState} from 'react';
import api from '../../lib/api';

export default function AdminProducts(){
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({name:'',slug:'',price:0,stock:0,description:''});
  const [filesById, setFilesById] = useState({});

  useEffect(()=>{ load(); },[]);

  async function load(){
    setLoading(true);
    try{
      const r = await api.get('/admin/products');
      const data = r.data;
      const list = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setProducts(list);
    }catch(err){
      console.error('Load products (admin) failed:', err);
      // Show a friendly message if unauthorized or server error
      const status = err.response?.status;
      if (status === 401 || status === 403) {
        alert('Akses admin diperlukan. Silakan login sebagai admin.');
      } else {
        alert('Gagal memuat produk admin');
      }
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }

  async function create(){
    await api.post('/admin/products', form);
    setForm({name:'',slug:'',price:0,stock:0,description:''});
    load();
  }

  async function remove(id){
    if (!confirm('Hapus?')) return;
    await api.delete(`/admin/products/${id}`);
    load();
  }

  function onChooseFile(e, id){
    const file = e.target.files?.[0];
    if (file){
      setFilesById(prev => ({...prev, [id]: file}));
    }
  }

  async function uploadImage(id){
    const file = filesById[id];
    if (!file) return alert('Pilih file gambar terlebih dahulu.');
    const fd = new FormData();
    fd.append('image', file);
    await api.post(`/admin/products/${id}/image`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
    alert('Gambar terunggah.');
    load();
  }

  return (
    <div className="font-sans">
      <div className="container py-6">
        <header className="flex items-center justify-between mb-4">
          <strong className="text-lg">Admin</strong>
          <nav className="flex gap-4 text-sm">
            <a href="/admin/products" className="underline">Products</a>
            <a href="/admin/orders" className="underline">Orders</a>
            <a href="/admin/custom-orders" className="underline">Custom Orders</a>
            <a href="#" className="underline" onClick={(e)=>{e.preventDefault(); localStorage.removeItem('hr_token'); localStorage.removeItem('hr_user'); window.location.href='/admin/login';}}>Logout</a>
          </nav>
        </header>
        <h2 className="text-2xl font-semibold mb-4">Admin - Products</h2>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="card p-4">
            <h3 className="font-semibold mb-3">Create product</h3>
            <div className="space-y-2">
              <input className="input" placeholder="name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} />
              <input className="input" placeholder="slug" value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})} />
              <input className="input" placeholder="price" type="number" value={form.price} onChange={e=>setForm({...form,price:parseInt(e.target.value||0)})} />
              <input className="input" placeholder="stock" type="number" value={form.stock} onChange={e=>setForm({...form,stock:parseInt(e.target.value||0)})} />
              <textarea className="input" placeholder="description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} />
              <button className="btn btn-primary w-full" onClick={create}>Create</button>
            </div>
          </div>

          <div className="lg:col-span-2 card p-4 overflow-x-auto">
            <h3 className="font-semibold mb-3">Products</h3>
            {loading && <div>Loading...</div>}
            <table className="table min-w-full">
              <thead className="bg-gray-50"><tr><th>ID</th><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Upload</th><th>Action</th></tr></thead>
              <tbody>
                {products.map(p=> (
                  <tr key={p.id}>
                    <td>{p.id}</td>
                    <td>{p.image ? <img alt="img" src={p.image} className="w-16 h-16 object-cover rounded"/> : '-'}</td>
                    <td className="max-w-[220px] truncate">{p.name}</td>
                    <td>Rp {p.price}</td>
                    <td>{p.stock}</td>
                    <td className="space-y-2">
                      <input className="block" type="file" accept="image/*" onChange={e=>onChooseFile(e,p.id)} />
                      <button className="btn btn-outline" onClick={()=>uploadImage(p.id)}>Upload</button>
                    </td>
                    <td><button className="btn btn-outline" onClick={()=>remove(p.id)}>Delete</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )
}
